def to_roman(n):
    """Convert an integer (1..3999) to a Roman numeral string."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("n must be an integer")
    if n < 1 or n > 3999:
        raise ValueError("n must be in range 1..3999")

    values = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I'),
    ]
    result = []
    for val, sym in values:
        while n >= val:
            result.append(sym)
            n -= val
    return ''.join(result)


def from_roman(s):
    """Convert a well-formed Roman numeral string back to an integer."""
    if not isinstance(s, str) or not s:
        raise ValueError("s must be a non-empty string")

    roman_values = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000,
    }

    # Parse and validate the numeral by re-encoding it
    total = 0
    prev = 0
    for ch in reversed(s):
        if ch not in roman_values:
            raise ValueError(f"Invalid character: {ch}")
        val = roman_values[ch]
        if val < prev:
            total -= val
        else:
            total += val
        prev = val

    # Round-trip check ensures standard subtractive form only
    if to_roman(total) != s:
        raise ValueError("Not a valid Roman numeral")

    return total
